angular.module("views/Enrollment/add-a-vet.html", []).run(["$templateCache", function($templateCache) {
  $templateCache.put("views/Enrollment/add-a-vet.html",
    "<div data-ng-controller=\"addAVetController as controller\">\n" +
    "\n" +
    "    <div class=\"center\">\n" +
    "        <h1 ng-hide=\"controller.successfullyAddedVet\">Add Your Favorite Clinic to Your Account</h1>\n" +
    "        <h1 ng-show=\"controller.successfullyAddedVet\"><span class=\"icon icon-check dkgreen\"></span><span class=\"dkgreen\"> Success! </span><br /> You have added a clinic to your favorites! Thank you!</h1>\n" +
    "        <p class=\"font-20 col-md-8 col-md-offset-2\">Adding clinics to your account helps us process your claims faster. You’re always free to visit any vet, specialist, or emergency clinic in the U.S. or Canada. </p>\n" +
    "    </div>\n" +
    "\n" +
    "    <form ng-hide=\"controller.successfullyAddedVet\" name=\"searchForm\" ng-submit=\"controller.search()\" novalidate class=\"clear center\">\n" +
    "\n" +
    "        <fieldset class=\"center\">\n" +
    "            <section>\n" +
    "                <div ng-show=\"controller.error\">\n" +
    "                    <p ng-bind=\"controller.errorMessage\" class=\"formErrors\"></p>\n" +
    "                </div>\n" +
    "                <h5>Search by:</h5>\n" +
    "                <select ng-model=\"controller.searchType\">\n" +
    "                        <option selected=\"selected\" value=\"companyName\">Clinic Name</option>\n" +
    "                        <option value=\"zipcode\">Zip Code</option>\n" +
    "                        <option value=\"city\">City And State</option>\n" +
    "                        <option value=\"phoneNum\">Clinic Phone Number</option>\n" +
    "                    </select>\n" +
    "        \n" +
    "                    <input required ng-model=\"controller.searchInput\" />\n" +
    "                    <select required ng-show=\"controller.searchType=='city'\" ng-model=\"controller.selectedState\" ng-options=\"state.abbreviation for state in controller.states\"></select>\n" +
    "                    <input type=\"button\" ng-click=\"controller.search()\" value=\"Search\">\n" +
    "            </section>\n" +
    "            \n" +
    "\n" +
    "        </fieldset>\n" +
    "\n" +
    "\n" +
    "    </form>\n" +
    "\n" +
    "    <h5 ng-show=\"controller.noVetsFound\" class=\"center\">No vets found with that search! Please try again.</h5>\n" +
    "\n" +
    "    <div class=\"searchAddVet top20\">\n" +
    "        <ul class=\"two-col\">\n" +
    "            <li ng-show=\"!controller.successfullyAddedVet && !controller.noVetsFound\" ng-repeat=\"vet in controller.returnedVets\">\n" +
    "                <div><strong>{{vet.name}}</strong> <br />{{vet.street1}}&nbsp;&nbsp;&nbsp;{{vet.city}}, {{vet.state}}</div>\n" +
    "                <button ng-click=\"controller.addVetToAccount(vet.vetId)\" class=\"remove-bytn-styles blue-font-link more-info no-space more-link-margin\"> <img src=\"https://d3544la1u8djza.cloudfront.net/Sidney/assets/img/star.png\" style=\"vertical-align:-5px;\" /> Add to my favorites</button>\n" +
    "            </li>\n" +
    "        </ul>\n" +
    "    </div>\n" +
    "\n" +
    "    <div ng-hide=\"controller.successfullyAddedVet\" class=\"clear col-md-8 col-md-offset-2\">\n" +
    "        <h3 class=\"orange2 center\">Help! My clinic isn’t here!</h3>\n" +
    "        <p class=\"center font-20\">Don’t worry – that just means we aren’t familiar with them yet, and you can skip this. We’ll enter and save your clinic’s information when we process your first claim. </p>\n" +
    "    </div>\n" +
    "</div>");
}]);

