angular.module("views/Enrollment/old-thank-you.html", []).run(["$templateCache", function($templateCache) {
  $templateCache.put("views/Enrollment/old-thank-you.html",
    "<div class=\"heading\">\n" +
    "            <h1>\n" +
    "                <span class=\"icon icon-check dkgreen\"></span><span class=\"dkgreen\"> Success! </span><br />\n" +
    "                <span ng-show=\"controller.data.quoteRequest.pets.length <=1\">{{controller.data.quoteRequest.pets[0].name}} has been enrolled!</span>\n" +
    "                <span ng-show=\"controller.data.quoteRequest.pets.length > 1\">Your pets have been enrolled!</span>\n" +
    "            </h1>\n" +
    "        </div>\n" +
    "\n" +
    "         <p class=\"subtitle lead text-center\">Account Number: <strong id=\"accountNumber\">{{controller.data.quoteRequest.accountNumber}}</strong></p>\n" +
    "        <div ng-include=\"'views/quote/premium-detail.html'\" style=\"max-width:800px; margin:40px auto;\"></div>\n" +
    "\n" +
    "        <div data-ng-controller=\"addAVetController as controller\" class=\"slideDown2\">\n" +
    "\n" +
    "        <div ng-hide=\"controller.successfullyAddedVet\" id=\"vetSearch\" class=\"d_flex f_direction--col\">\n" +
    "            <hr class=\"space clear\" style=\"padding-top:20px;\" />\n" +
    "            <div class=\"h-hr width-100 clear\">\n" +
    "                <h2 class=\"subtitle heading--md text-center mt_0\">What's Next?</h2>\n" +
    "            </div>\n" +
    "            <div class=\"col-md-8 col-md-offset-2\">\n" +
    "                <div class=\"text-center\">\n" +
    "                    <span class=\"icon icon-clinic m-icon orange2\" role=\"img\" aria-hidden=\"true\"></span>\n" +
    "                    <h3 class=\"mt_0\">Add Your Favorite Clinic For Faster Claims Processing</h3>\n" +
    "                    <p>You’re always free to visit any vet, specialist, or emergency clinic in the U.S. or Canada. Add the ones you visit frequently to your account to speed up the processing of your claims!</p>\n" +
    "                </div>\n" +
    "            </div>\n" +
    "\n" +
    "            <form name=\"searchForm\" ng-submit=\"controller.search()\" novalidate class=\"clear text-center\" style=\"display: flex; justify-content: center;\">\n" +
    "\n" +
    "                <div class=\"vetSearch_wrapper\">\n" +
    "                    <div class=\"form_fieldWrapper a_items--center mb_0--md mb_16 mr_16\" style=\"flex-direction: row;\">\n" +
    "                        <label for=\"searchByType\" class=\"form_label mr_8 mb_0\" style=\"white-space: nowrap;\">Search by:</label>\n" +
    "                        <div class=\"input--selectWrapper\">\n" +
    "                            <select ng-model=\"controller.searchType\" id=\"searchByType\" class=\"form_input input--select\">\n" +
    "                                <option selected=\"selected\" value=\"companyName\">Clinic Name</option>\n" +
    "                                <option value=\"zipcode\">Zip Code</option>\n" +
    "                                <option value=\"city\">City and State</option>\n" +
    "                                <option value=\"phoneNum\">Clinic Phone Number</option>\n" +
    "                            </select>\n" +
    "                        </div>\n" +
    "                    </div>\n" +
    "    \n" +
    "                    <!-- Clinic Name -->\n" +
    "                    <div ng-show=\"controller.searchType=='companyName'\" class=\"form_fieldWrapper mb_0--md mb_16\">\n" +
    "                        <label for=\"typeCompanyName\" class=\"sr-only\">Clinic Name</label>\n" +
    "                        <input class=\"form_input\" id=\"typeCompanyName\" ng-model=\"controller.searchInput\" placeholder=\"Clinic Name\" />\n" +
    "                    </div>\n" +
    "    \n" +
    "                    <!-- Zip Code -->\n" +
    "                    <div ng-show=\"controller.searchType=='zipcode'\" class=\"form_fieldWrapper mb_0--md mb_16\">\n" +
    "                        <label for=\"typeZipCode\" class=\"sr-only\">Zip Code</label>\n" +
    "                        <input class=\"form_input\" id=\"typeZipCode\" ng-model=\"controller.searchInput\" placeholder=\"Zip Code\" />\n" +
    "                    </div>\n" +
    "    \n" +
    "                    <!-- City, State -->\n" +
    "                    <div ng-show=\"controller.searchType=='city'\" class=\"form_fieldWrapper mb_0--md mb_16\">\n" +
    "                        <label for=\"typeCity\" class=\"sr-only\">City</label>\n" +
    "                        <input class=\"form_input mb_8\" id=\"typeCity\" ng-model=\"controller.searchInput\" type=\"text\" style=\"float: none;\" placeholder=\"City\" />\n" +
    "    \n" +
    "                        <label for=\"selectState\" class=\"sr-only\">State</label>\n" +
    "                        <div class=\"input--selectWrapper\">\n" +
    "                            <select class=\"form_input input--select\" id=\"selectState\" ng-model=\"controller.selectedState\" ng-options=\"state.abbreviation for state in controller.states\"></select>\n" +
    "                        </div>\n" +
    "                    </div>\n" +
    "    \n" +
    "                    <!-- Phone Number -->\n" +
    "                    <div ng-show=\"controller.searchType=='phoneNum'\" class=\"form_fieldWrapper mb_0--md mb_16\">\n" +
    "                        <label for=\"typePhoneNum\" class=\"sr-only\">Phone Number</label>\n" +
    "                        <input class=\"form_input\" id=\"typePhoneNum\" ng-model=\"controller.searchInput\" type=\"tel\" placeholder=\"3305556789\" />\n" +
    "                    </div>\n" +
    "    \n" +
    "                    <button type=\"button\" ng-click=\"controller.search()\" class=\"button button-sm button_primary mb_0 mt_0 mr_0 ml_16--md ml_0\">Search</button>\n" +
    "                </div>\n" +
    "            </form>\n" +
    "\n" +
    "            <div aria-live=\"polite\">\n" +
    "                <div ng-if=\"controller.noVetsFound\" class=\"d_flex f_direction--row a_items--center j_content--center mt_24\">\n" +
    "                    <img src=\"https://d3544la1u8djza.cloudfront.net/APHI/sidney/icons/icon_error.svg\" alt=\"Error:\" class=\"icon_error--inline\" />\n" +
    "                    <p class=\"text-center formErrors\" style=\"font-size: 1.125rem;\">No vets found with that search! Please try again.</p>\n" +
    "                </div>\n" +
    "\n" +
    "            </div>\n" +
    "\n" +
    "            <div class=\"searchAddVet mt_16\">\n" +
    "                <ul class=\"two-col mt_16\" style=\"display: grid;grid-template-columns: 1fr 1fr; place-items: center;\">\n" +
    "                    <li ng-show=\"!controller.successfullyAddedVet && !controller.noVetsFound\" ng-repeat=\"vet in controller.returnedVets\" style=\"margin-bottom: 16px;\">\n" +
    "                        <div><strong>{{vet.name}}</strong> <br />{{vet.street1}}&nbsp;&nbsp;&nbsp;{{vet.city}}, {{vet.state}}</div>\n" +
    "                        <!--remove-bytn-styles blue-font-link more-info no-space more-link-margin-->\n" +
    "                        <button ng-click=\"controller.addVetToAccount(vet.vetId)\" class=\"link_primary\" aria-label=\"Add {{vet.name}} to my favorites\"> <img src=\"https://d3544la1u8djza.cloudfront.net/Sidney/assets/img/star.png\" alt=\"\" style=\"vertical-align:-5px;\" /> Add to my favorites</button>\n" +
    "                    </li>\n" +
    "                </ul>\n" +
    "            </div>\n" +
    "            <hr class=\"space clear\" style=\"padding-top:20px;\" />\n" +
    "\n" +
    "            <div ng-show=\"controller.searchPerformed\" class=\"clear text-center width-60\" style=\"width: 60%; margin: 0 auto;\">\n" +
    "                <h3 class=\"text-center\">Help! My clinic isn’t here!</h3>\n" +
    "                <p class=\"text-center font-20\">Don’t worry – that just means we aren’t familiar with them yet, and you can skip this. We’ll enter and save your clinic’s information when we process your first claim. </p>\n" +
    "            </div>\n" +
    "        </div>\n" +
    "        <div ng-show=\"controller.successfullyAddedVet\" id=\"vetAdded\" class=\"clear text-center width-60\">\n" +
    "            <h3><span class=\"icon icon-check dkgreen\" role=\"img\" aria-hidden=\"true\"></span><span class=\"dkgreen\"> Thank You! </span></h3>\n" +
    "            <p>Adding clinics to your account helps us process your claims faster. You’re always free to visit any vet, specialist, or emergency clinic in the U.S. or Canada. </p>\n" +
    "        </div>\n" +
    "    </div>\n" +
    "\n" +
    "      <div class=\"h-hr width-100 mt_48 clear\">\n" +
    "        <h2 class=\"subtitle heading--md text-center mt_0\">Register now, save time later</h2>\n" +
    "    </div>\n" +
    "\n" +
    "    <h3 class=\"text-center width-60\" style=\"width: 60%; margin: 0 auto;\">Just enter a password to register in the Member Center. Log in anytime to manage your account.</h3>\n" +
    "    <div class=\"row mt_32\">\n" +
    "        <div class=\"col-md-4 col-md-offset-3\">\n" +
    "            <form name=\"form\" ng-submit=\"controller.submit()\" class=\"thankyou\">\n" +
    "                <fieldset>\n" +
    "                    <div class=\"form_fieldWrapper\">\n" +
    "                        <label for=\"loginEmailAddress\" class=\"form_label\">Email Address</label>\n" +
    "                        <input id=\"loginEmailAddress\" type=\"text\" ng-model=\"controller.data.quoteRequest.emailAddress\" readonly disabled class=\"form_input mb_0\">\n" +
    "                        <div aria-live=\"polite\">\n" +
    "                            <div ng-if=\"form.$submitted || form.loginPassword.$touched && form.loginPassword.$invalid\" class=\"d_flex f_direction--row a_items--center\">\n" +
    "                                <img src=\"https://d3544la1u8djza.cloudfront.net/APHI/sidney/icons/icon_error.svg\" alt=\"Error:\" class=\"icon_error--inline\" />\n" +
    "                                <p class=\"formErrors\" ng-if=\"form.loginPassword.$error.required\" ng-bind=\"controller.messages.invalidPassword\"></p>\n" +
    "                            </div>\n" +
    "                        </div>\n" +
    "                    </div>\n" +
    "\n" +
    "                    <div class=\"form_fieldWrapper\">\n" +
    "                        <div class=\"input_wrapper\">\n" +
    "                            <label for=\"loginPassword\" class=\"form_label\">Password</label>\n" +
    "                            <input id=\"loginPassword\" name=\"loginPassword\" type=\"password\" ng-model=\"controller.user.password\" ng-required=\"true\"  class=\"form_input mb_0\" aria-describedby=\"register_loginInfo--passwordInstructions\">\n" +
    "                            <span id=\"register_loginInfo--passwordInstructions\" class=\"input_hintText\"><strong>Must include:</strong> At least 6 characters, 1 special character and 1 number</span>\n" +
    "                        </div>\n" +
    "                        <div aria-live=\"polite\">\n" +
    "                            <div ng-if=\"form.$submitted || form.confirmPassword.$touched &&  form.confirmPassword.$invalid\" class=\"d_flex f_direction--row a_items--center\">\n" +
    "                                <img src=\"https://d3544la1u8djza.cloudfront.net/APHI/sidney/icons/icon_error.svg\" alt=\"Error:\" class=\"icon_error--inline\" />\n" +
    "                                <p class=\"formErrors\" ng-if=\"form.confirmPassword.$error.required\" ng-bind=\"controller.messages.invalidConfirmPassword\"></p>\n" +
    "                                <p class=\"formErrors\" ng-if=\"form.confirmPassword.$invalid\" ng-bind=\"controller.messages.invalidPasswordMatch\"></p>\n" +
    "                            </div>\n" +
    "                        </div>\n" +
    "                    </div>\n" +
    "\n" +
    "                    <div class=\"form_fieldWrapper\">\n" +
    "                        <label for=\"confirmPassword\" class=\"form_label\">Confirm Password</label>\n" +
    "                        <input id=\"confirmPassword\" name=\"confirmPassword\" type=\"password\" ng-model=\"controller.confirmPassword\"  class=\"form_input mb_0\" compare-to=\"controller.user.password\" ng-required=\"true\">\n" +
    "                    </div>\n" +
    "\n" +
    "                </fieldset>\n" +
    "                <button type=\"submit\" class=\"button button-lg button_primary\">Register</button>\n" +
    "            </form>\n" +
    "        </div>\n" +
    "\n" +
    "        <div class=\"col-md-5 hidden-xs\">\n" +
    "            <ul class=\"checklist-small mt_32\">\n" +
    "                <li>Submit and track claims</li>\n" +
    "                <li>Review your benefits</li>\n" +
    "                <li>Pay your bill and see your billing history</li>\n" +
    "                <li>Find answers to FAQs</li>\n" +
    "                <li>Find a nearby vet clinic</li>\n" +
    "                <li>Update your contact info</li>\n" +
    "                <li>Sign up for direct deposit</li>\n" +
    "                <li>Get in touch with us</li>\n" +
    "                <!-- <li>{{controller.pepperJamPixel}}</li>\n" +
    "                <li>{{controller.pepperJamEnabled}}</li>\n" +
    "                <li>{{controller.quoteId}}</Vli> -->\n" +
    "            </ul>\n" +
    "        </div>\n" +
    "    </div>\n" +
    "\n" +
    "     <div style=\"max-height: 1px\">\n" +
    "        <img src=\"{{brandTrackingPixel}}\" alt=\"\" />\n" +
    "    </div>\n" +
    "    <div style=\"max-height: 1px\" ng-if=\"controller.siteConfig.brand == 'APHI' && controller.pepperJamEnabled\">\n" +
    "        <iframe sandbox=\"allow-same-origin allow-scripts allow-popups allow-forms\" ng-src=\"{{controller.pepperJamPixel | trusted}}\" width=\"1\" height=\"1\" frameborder=\"0\" />\n" +
    "    </div>");
}]);

angular.module("views/Enrollment/partials/discount-summary.html", []).run(["$templateCache", function($templateCache) {
  $templateCache.put("views/Enrollment/partials/discount-summary.html",
    "<p ng-if=\"controller.data.quoteRequest.priorityCode\" class=\"no-space discount-summary__priority-code\">\n" +
    "    Priority Code: <span class=\"text-bold\" ng-bind=\"controller.data.quoteRequest.priorityCode\"></span>\n" +
    "</p>\n" +
    "<p class=\"discount discount-summary__message\"\n" +
    "    ng-hide=\"controller.data.totalAnnualDiscount==0 || controller.data.quoteHasPetWithVft()\">\n" +
    "    You've\n" +
    "    saved {{controller.data.totalAnnualDiscount| currency:\"$\"}} annually with your {{controller.getTypeOfDiscount()}}\n" +
    "    discount!\n" +
    "</p>\n" +
    "<p class=\"discount discount-summary__message\"\n" +
    "    ng-show=\"controller.data.totalAnnualDiscount!=0 && controller.data.quoteHasPetWithVft()\">\n" +
    "    You'll\n" +
    "    save {{controller.data.totalAnnualDiscount | currency:'$'}} on your first year of coverage!\n" +
    "</p>\n" +
    "<p class=\"discount-summary__vet-note\"\n" +
    "    ng-if=\"controller.data.totalAnnualDiscount!=0 && controller.data.isWashingtonCustomer()\">\n" +
    "    <span>For our vet student/staff discount, call 1-800-799-5852.</span>\n" +
    "</p>");
}]);

