angular.module("views/quote/partials/payment-renewal-terms.html", []).run(["$templateCache", function($templateCache) {
  $templateCache.put("views/quote/partials/payment-renewal-terms.html",
    "<!-- Payment and Renewal Terms Agreement Section -->\n" +
    "<div ng-if=\"!controller.siteConfig.submittedApplication\" class=\"terms__agreement\">\n" +
    "    <label class=\"customCheckbox\" for=\"agreePaymentTerms\">\n" +
    "        <input type=\"checkbox\" id=\"agreePaymentTerms\" name=\"agreePaymentTerms\" aria-expanded=\"false\"\n" +
    "            aria-controls=\"paymentAndRenewal\" ng-model=\"controller.paymentAndRenewalTerms\" ng-true-value=\"1\"\n" +
    "            ng-required=\"!controller.siteConfig.submittedApplication\" ng-click=\"controller.paymentAndRenewalTerms()\"\n" +
    "            data-toggle=\"collapse\" data-parent=\"#accordion\" data-target=\"#paymentAndRenewal\"\n" +
    "            aria-describedby=\"{{(form.$submitted || form.agreePaymentTerms.$touched) && form.agreePaymentTerms.$invalid ? 'agreePaymentTerms-error' : ''}}\"\n" +
    "            aria-required=\"true\" />\n" +
    "        <svg width=\"32\" height=\"32\" viewBox=\"-4 -4 39 39\" aria-hidden=\"true\" focusable=\"false\">\n" +
    "            <!-- The background -->\n" +
    "            <rect class=\"customCheckbox--bg\" width=\"35\" height=\"35\" x=\"-2\" y=\"-2\" stroke=\"currentColor\" fill=\"none\"\n" +
    "                stroke-width=\"3\" rx=\"6\" ry=\"6\"></rect>\n" +
    "            <polyline class=\"customCheckbox--cm\" points=\"4,14 12,23 28,5\" stroke=\"transparent\" stroke-width=\"4\"\n" +
    "                fill=\"none\"></polyline>\n" +
    "        </svg>\n" +
    "        <span>I agree to the <span class=\"terms__compliance-link link_complianceCheckbox link_primary\" role=\"button\"\n" +
    "                tabindex=\"0\" aria-controls=\"paymentAndRenewal\" aria-expanded=\"false\" data-toggle=\"collapse\"\n" +
    "                data-target=\"#paymentAndRenewal\">payment and renewal terms</span>. <span\n" +
    "                aria-hidden=\"true\">*</span><span class=\"sr-only\">required</span></span>\n" +
    "    </label>\n" +
    "    <div ng-if=\"(form.$submitted || form.agreePaymentTerms.$touched) && form.agreePaymentTerms.$invalid\">\n" +
    "        <div class=\"d_flex f_direction--row a_items--center\">\n" +
    "            <img src=\"https://d3544la1u8djza.cloudfront.net/APHI/sidney/icons/icon_error.svg\" alt=\"Error icon\"\n" +
    "                class=\"icon_error--inline\" />\n" +
    "            <p ng-bind=\"controller.messages.agreeToTerms\" class=\"formErrors\" id=\"agreePaymentTerms-error\" role=\"alert\">\n" +
    "            </p>\n" +
    "        </div>\n" +
    "    </div>\n" +
    "</div>\n" +
    "\n" +
    "<!-- Payment and Renewal Terms Collapsible Section -->\n" +
    "<div id=\"paymentAndRenewal\" class=\"collapse clear terms__details\" aria-hidden=\"true\">\n" +
    "    <h3 class=\"sr-only\">Payment and Renewal Terms Details</h3>\n" +
    "    <p>\n" +
    "        <strong>Payment and Renewal Terms:</strong> By enrolling in this policy, you authorize us to charge your chosen\n" +
    "        payment method for your premium and any\n" +
    "        applicable fees.\n" +
    "    </p>\n" +
    "    <p>If you pay monthly, your payment will be charged each month on the date listed on your declarations page. If you\n" +
    "        pay annually, your payment will be charged once per policy period on the date listed on your declarations page.\n" +
    "        Your policy automatically renews at the end of each 12-month policy period unless you take action to cancel such\n" +
    "        renewal.</p>\n" +
    "    <p>Your coverage and rates may change at renewal. You will receive advance written notice of any changes before your\n" +
    "        next policy period begins. Your renewal declarations page will specify your updated coverage and rates. By\n" +
    "        continuing coverage, you accept the terms outlined on your renewal declarations page.</p>\n" +
    "    <p>Upon receipt of your renewal notice, you may choose to cancel the automatic renewal of your policy. If you choose\n" +
    "        not to renew, you must notify us no later than the day before your policy's renewal effective date. During this\n" +
    "        renewal window, you may cancel the automatic renewal of your policy through your member center or by contacting\n" +
    "        us via email, phone, or in writing. If you choose not to cancel the automatic renewal of your policy, you will\n" +
    "        be unable to cancel the automatic renewal of your policy until your next renewal window.</p>\n" +
    "    <p>To cancel your policy at any time, you must contact us by email, phone, or in writing and specify the\n" +
    "        cancellation date. Written notification may be sent via email, fax, or mail. If you cancel, we will provide a\n" +
    "        pro-rated refund of any unused premium based on your last date of coverage.</p>\n" +
    "    <p>Your policy documents will indicate whether a money-back guarantee applies. If applicable, this guarantee is only\n" +
    "        available during your first policy period and does not apply to renewals. </p>\n" +
    "    <p>If you fail to make a payment, we may cancel your policy for nonpayment. Advance notice of cancellation will be\n" +
    "        sent per state requirements.</p>\n" +
    "</div>");
}]);

